/// The fields of `BasketInputForm`, each with its label, its value as sent,
/// the attributes the input type's rules give it and its errors; a nested
/// object's in a fieldset, and a list's rows with their buttons. `form` is
/// a new form when the page passes none, and `choices` turns a text or
/// number field the app names into a select.
#[component]
pub async fn basket_input_fields(
    #[default(BasketInputForm::new())] form: BasketInputForm,
    #[default] errors: FormErrors,
    #[default] choices: Choices,
) -> topcoat::Result<impl View> {
    let form_errors = errors.unshown(BasketInputForm::shows);
    Ok(view! {
        // The button Enter presses, ahead of every row button: it submits
        // the form without an `_action`.
        <button type="submit" class="ss-submit" hidden=(true)></button>
        for message in form_errors {
            <p class="form-error">(message)</p>
        }
        <fieldset class="ss-list" data-field="lines">
            <legend>"Lines"</legend>
            for message in errors.of("lines") {
                <p class="field-error">(message)</p>
            }
            #[key(i0)]
            for (i0, row0) in form.lines.iter().enumerate() {
                <fieldset class="ss-row">
                    let row = format!("lines[{i0}]");
                    let label = format!("Lines {}", i0 + 1);
                    <legend>(&label)</legend>
                    <input type="hidden" name=(&row) value="">
                    for message in errors.of(&row) {
                        <p class="field-error">(message)</p>
                    }
                    <div class="field">
                        let name = format!("lines[{i0}].itemId");
                        let id = format!("basket-input-lines-{i0}-item-id");
                        <label for=(&id)>"Item id"</label>
                        match choices.of(&name, "lines.itemId") {
                            Some(options) => choice_select(id: &id, name: &name, required: true, invalid: errors.invalid(&name), options: choice_options(options, row0.item_id.as_deref())),
                            None => <input id=(&id) name=(&name) type="text" required=(true) pattern="^([0-9A-Za-z]{1,22}|[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})$" value=(row0.item_id.clone()) aria-invalid=(errors.invalid(&name))>,
                        }
                        for message in errors.of(&name) {
                            <p class="field-error">(message)</p>
                        }
                    </div>
                    <div class="field">
                        let name = format!("lines[{i0}].quantity");
                        let id = format!("basket-input-lines-{i0}-quantity");
                        <label for=(&id)>"Quantity"</label>
                        match choices.of(&name, "lines.quantity") {
                            Some(options) => choice_select(id: &id, name: &name, required: true, invalid: errors.invalid(&name), options: choice_options(options, row0.quantity.as_deref())),
                            None => <input id=(&id) name=(&name) type="number" required=(true) step="any" min="1" max="9" value=(row0.quantity.clone()) aria-invalid=(errors.invalid(&name))>,
                        }
                        for message in errors.of(&name) {
                            <p class="field-error">(message)</p>
                        }
                    </div>
                    if form.lines.len() > 1 {
                        <button type="submit" class="ss-remove" name="_action" value=(format!("remove:{row}")) formnovalidate=(true) aria-label=(format!("Remove {label}"))>"Remove"</button>
                    }
                </fieldset>
            }
            if form.lines.len() < 5 {
                <button type="submit" class="ss-add" name="_action" value="add:lines" formnovalidate=(true)>"Add"</button>
            }
        </fieldset>
    })
}

/// The arguments of catalog.listItems, each as the browser sends it. A filter,
/// sent by GET and read from the query.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct CatalogListItemsArgsForm {
    pub ids: Vec<String>,
    pub in_stock: Option<String>,
    /// The page asked for (D60): the cursor of the page before, a page's
    /// `next`, and the limit, as the query sends them. No control renders
    /// them, and `page` reads them by the route's rules.
    pub cursor: Option<String>,
    pub limit: Option<String>,
    /// The order the page is asked for in (D60, amended), the `sort` query
    /// parameter as sent, which `page` reads by the route's rules: none for
    /// its defaultSort. No control renders it; a sorted list's headers set
    /// it.
    pub sort: Option<String>,
    /// The browser sent more than `MAX_PAIRS` pairs, past which the form
    /// read none: `parse` refuses it with the form's error.
    pub overflow: bool,
}

impl CatalogListItemsArgsForm {
    /// How a page sends the form: `<form method=(Self::METHOD)>`.
    pub const METHOD: &'static str = "get";

    /// A new form: each argument's declared default.
    pub fn new() -> Self {
        Self {
            ids: Vec::new(),
            in_stock: None,
            cursor: None,
            limit: None,
            sort: None,
            overflow: false,
        }
    }

    /// The form a browser sent, from its pairs: each argument's first value and
    /// a list's every value. `Form<CatalogListItemsArgsForm>` decodes a query
    /// this way.
    pub fn from_pairs(pairs: impl IntoIterator<Item = (String, String)>) -> Self {
        let posted = Posted::from_pairs(pairs);
        Self {
            ids: posted.get("ids").values(true),
            in_stock: posted.get("inStock").first(),
            cursor: posted.get("cursor").first(),
            limit: posted.get("limit").first(),
            sort: posted.get("sort").first(),
            overflow: posted.overflow,
        }
    }

    /// The filter the current request's query holds, so a page's form shows
    /// the filters in effect: what `Form<CatalogListItemsArgsForm>` reads on GET.
    pub fn from_query(cx: &Cx) -> topcoat::Result<Self> {
        let query = uri(cx).query().unwrap_or_default();
        Ok(Form::<Self>::from_bytes(query.as_bytes())?.0)
    }

    /// The operation's arguments: each written as the JSON a request carries
    /// and decoded into its type, then checked as the router checks a request's
    /// (`Args::check`); else each control's errors, or the form's when the
    /// browser sent more than it reads. `check` refuses the first argument that
    /// breaks a rule.
    pub fn parse(&self) -> Result<crate::api::CatalogListItemsArgs, FormErrors> {
        if self.overflow {
            return Err(overflowed());
        }
        let mut errors = FormErrors::default();
        let arg_ids = list(&mut errors, "ids", &self.ids, text);
        let arg_in_stock = single(&mut errors, "inStock", yes_no(self.in_stock.as_deref()));
        let page = match self.page() {
            Ok(page) => Some(page),
            Err(err) => {
                errors.merge(FormErrors::from_api(&err));
                None
            }
        };
        let Some(arg_ids) = arg_ids else {
            return Err(errors);
        };
        let Some(arg_in_stock) = arg_in_stock else {
            return Err(errors);
        };
        let Some(page) = page else {
            return Err(errors);
        };
        let args = crate::api::CatalogListItemsArgs {
            ids: arg_ids,
            in_stock: arg_in_stock,
            page,
        };
        args.check().map_err(|err| FormErrors::from_api(&err))?;
        Ok(args)
    }

    /// The page the form asks for, its `cursor`, `limit` and `sort` read by
    /// the route's rules (`PageSpec::query`, D60, amended): an absent cursor
    /// is the first page, an absent limit the route's default and an absent
    /// sort its defaultSort, which the call fills in, and a refusal is the
    /// router's 400 at the first it refuses. The cursor is still bound to
    /// its sort; the in-process call unbinds it.
    pub fn page(&self) -> Result<runtime::page::PageRequest, ApiError> {
        let pairs = [("cursor", &self.cursor), ("limit", &self.limit), ("sort", &self.sort)]
            .into_iter()
            .filter_map(|(name, value)| value.clone().map(|value| (name.to_owned(), value)))
            .collect();
        crate::api::CatalogListItemsArgs::PAGE.query(&QueryValues::new(pairs))
    }

    /// The pairs the form holds as a query sends them, in control order:
    /// each argument's values as sent, then the sort and `limit` when sent,
    /// never `cursor`. A page links the next page and the first with them,
    /// so each keeps the filter, the order and the limit.
    pub fn query_pairs(&self) -> Vec<(String, String)> {
        let mut pairs = Vec::new();
        pairs.extend(self.ids.iter().map(|value| ("ids".to_owned(), value.clone())));
        if let Some(value) = &self.in_stock {
            pairs.push(("inStock".to_owned(), value.clone()));
        }
        if let Some(sort) = &self.sort {
            pairs.push(("sort".to_owned(), sort.clone()));
        }
        if let Some(limit) = &self.limit {
            pairs.push(("limit".to_owned(), limit.clone()));
        }
        pairs
    }

    /// Parses the form, then calls the operation in-process
    /// (`operations::catalog_list_items`). A refusal is the status a page
    /// answers with and the errors it renders the form again with: 422 and
    /// `parse`'s errors, or the route's status (401, 403, 404, 409, ...) and
    /// the operation's errors (`Refusal::from_api`).
    pub async fn submit(&self, cx: &Cx) -> Result<runtime::page::Page<types::ItemView>, Refusal> {
        // A cursor or a limit the route refuses is its 400, as the router
        // answers it.
        self.page().map_err(|err| Refusal::from_api(&err))?;
        let args = self.parse()?;
        operations::catalog_list_items(cx, args).await.map_err(|err| Refusal::from_api(&err))
    }

    /// Whether the component shows the errors at `path`: at an argument's
    /// control. A path argument's are the form's own.
    fn shows(path: &[Segment]) -> bool {
        match path {
            [Segment::Key(key), rest @ ..] => match key.as_str() {
                "ids" => shows_all(rest),
                "inStock" => rest.is_empty(),
                _ => false,
            },
            _ => false,
        }
    }
}

impl<'de> Deserialize<'de> for CatalogListItemsArgsForm {
    /// Reads the pairs a browser sends, as Topcoat's `Form` hands them, by
    /// `from_pairs`.
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        Vec::<(String, String)>::deserialize(deserializer).map(Self::from_pairs)
    }
}

